<?php
declare(strict_types=1);
require_once dirname(__DIR__, 3) . '/api/core/Env.php';
require_once dirname(__DIR__, 3) . '/api/assets/conn/db.php';
header_remove('Content-Type');
header('Content-Type: text/html; charset=utf-8', true);
function sa_h(mixed $value): string { return htmlspecialchars((string) $value, ENT_QUOTES, 'UTF-8'); }
$token = trim((string) ($_REQUEST['token'] ?? ''));
$lookup = $con->prepare('SELECT facility_nin, survey_date FROM social_audit_tokens WHERE token = ? AND valid_until >= NOW()');
$lookup->bind_param('s', $token); $lookup->execute(); $context = $lookup->get_result()->fetch_assoc(); $lookup->close();
if (!$context) { http_response_code(410); exit('<!doctype html><title>Survey unavailable</title><p>This Social Audit QR link is invalid or has expired.</p>'); }
$config = json_decode((string) file_get_contents(dirname(__DIR__, 3) . '/api/masters/social-audit/survey_questions.json'), true) ?: [];
$questions = []; foreach (($config['questions'] ?? []) as $question) foreach (($question['sub_questions'] ?? [$question]) as $item) $questions[] = $item;
$language = in_array($_POST['language'] ?? $_GET['language'] ?? '', ['en', 'hi'], true) ? ($_POST['language'] ?? $_GET['language']) : '';
$error = '';
if ($_SERVER['REQUEST_METHOD'] === 'POST' && $language !== '') {
    $answers = $_POST['answers'] ?? []; $respondent = hash('sha256', trim((string) ($_POST['respondent_key'] ?? '')));
    $valid = []; foreach ($questions as $q) { $id = (string) ($q['id'] ?? ''); $type = (string) ($q['type'] ?? 'yes_no'); $options = $config['answer_options'][$type][$language] ?? $config['answer_options'][$type]['en'] ?? []; $valid[$id] = array_map(static fn($o) => (string) $o['value'], $options); }
    if (count($answers) !== count($valid) || strlen($respondent) !== 64) $error = 'Please answer every question.';
    foreach ($valid as $id => $options) if (!isset($answers[$id]) || !in_array((string) $answers[$id], $options, true)) $error = 'One or more answers are invalid.';
    if ($error === '') { $exists = $con->prepare('SELECT 1 FROM social_audit_answers WHERE token = ? AND respondent_key = ? LIMIT 1'); $exists->bind_param('ss', $token, $respondent); $exists->execute(); $already = (bool) $exists->get_result()->fetch_row(); $exists->close(); if ($already) $error = 'This device has already submitted this survey.'; }
    if ($error === '') { $insert = $con->prepare('INSERT INTO social_audit_answers (token, facility_nin, survey_date, question_id, answer_value, language, respondent_key) VALUES (?, ?, ?, ?, ?, ?, ?)'); $con->begin_transaction(); try { foreach ($valid as $id => $_) { $answer = (string) $answers[$id]; $insert->bind_param('sssssss', $token, $context['facility_nin'], $context['survey_date'], $id, $answer, $language, $respondent); $insert->execute(); } $con->commit(); } catch (Throwable) { $con->rollback(); $error = 'Your answers could not be saved. Please try again.'; } }
    if ($error === '') { ?><!doctype html><meta name="viewport" content="width=device-width,initial-scale=1"><title>Thank you</title><style>body{font:16px Arial;background:#f4f7f9;display:grid;place-items:center;min-height:100vh;margin:0}.card{background:#fff;max-width:400px;padding:32px;border-radius:14px;text-align:center;box-shadow:0 8px 26px #1232}</style><div class="card"><h1>Thank you</h1><p><?= $language === 'hi' ? 'आपकी राय सफलतापूर्वक दर्ज हो गई है।' : 'Your opinion has been submitted successfully.' ?></p><?= $language === 'hi' ? '<audio autoplay src="/ui/assets/audio/social-audit/hi/thanks.mp3"></audio>' : '' ?></div><?php exit; }
}
?><!doctype html><html lang="<?= sa_h($language ?: 'en') ?>"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Social Audit Survey</title><style>body{font:16px Arial;background:#f4f7f9;display:grid;place-items:center;min-height:100vh;margin:0;padding:16px;box-sizing:border-box}.card{background:#fff;width:min(470px,100%);padding:24px;box-sizing:border-box;border-radius:14px;box-shadow:0 8px 26px #1232}.lang{text-align:center}.lang a,.nav button{display:inline-block;margin:6px;padding:11px 17px;border:0;border-radius:8px;background:#12628a;color:#fff;font-weight:bold;text-decoration:none}.question[hidden]{display:none}.progress{height:8px;background:#e5e7eb;border-radius:10px;overflow:hidden}.progress span{display:block;height:100%;background:#16805c}.option{display:block;margin:10px 0;padding:13px;border:1px solid #d6e0e5;border-radius:9px;font-weight:bold}.option:has(input:checked){border-color:#12628a;background:#eaf5fa}.nav{display:flex;justify-content:space-between;margin-top:16px}.nav button[disabled]{visibility:hidden}.error{color:#a12622}.audio{float:right;border:0;background:#fff;font-size:22px}</style><div class="card"><?php if (!$language) { ?><div class="lang"><button class="audio" type="button" data-a="/ui/assets/audio/social-audit/hi/language_select.mp3">🔊</button><h1>Social Audit Survey</h1><p>भाषा चुनें / Select language</p><a href="?token=<?= sa_h($token) ?>&language=en">English</a><a href="?token=<?= sa_h($token) ?>&language=hi">हिन्दी</a></div><script>document.querySelector('[data-a]').onclick=e=>new Audio(e.currentTarget.dataset.a).play().catch(()=>{});</script><?php } else { ?><h2><?= $language === 'hi' ? 'सामाजिक अंकेक्षण सर्वेक्षण' : 'Social Audit Survey' ?></h2><p id="counter"></p><div class="progress"><span id="bar"></span></div><?php if ($error) echo '<p class="error">' . sa_h($error) . '</p>'; ?><form method="post" id="survey"><input type="hidden" name="token" value="<?= sa_h($token) ?>"><input type="hidden" name="language" value="<?= sa_h($language) ?>"><input type="hidden" name="respondent_key" id="respondent"><div id="questions"></div><div class="nav"><button type="button" id="back">Back</button><button type="button" id="next">Next</button><button type="submit" id="submit" hidden>Submit</button></div></form><script>const qs=<?= json_encode($questions, JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES) ?>,opts=<?= json_encode($config['answer_options'] ?? [], JSON_UNESCAPED_UNICODE) ?>,lang=<?= json_encode($language) ?>;let n=0;const host=document.querySelector('#questions');const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));qs.forEach((q,i)=>{let a=(opts[q.type]?.[lang]||opts[q.type]?.en||[]).map(o=>`<label class="option"><input required type="radio" name="answers[${esc(q.id)}]" value="${esc(o.value)}"> ${esc(o.label)}</label>`).join('');let audio=lang==='hi'?`<button class="audio" type="button" data-a="/ui/assets/audio/social-audit/hi/${q.id}.mp3">🔊</button>`:'';host.insertAdjacentHTML('beforeend',`<section class="question" ${i?'hidden':''}>${audio}<h3>${esc(q.text[lang]||q.text.en)}</h3>${a}</section>`)});function show(){document.querySelectorAll('.question').forEach((e,i)=>e.hidden=i!==n);document.querySelector('#counter').textContent=`${n+1} / ${qs.length}`;document.querySelector('#bar').style.width=`${(n+1)*100/qs.length}%`;back.disabled=n===0;next.hidden=n===qs.length-1;submit.hidden=n!==qs.length-1}back.onclick=()=>{n--;show()};next.onclick=()=>{if(!document.querySelectorAll('.question')[n].querySelector(':checked'))return alert(lang==='hi'?'कृपया उत्तर चुनें':'Please select an answer');n++;show()};document.addEventListener('click',e=>{let p=e.target.dataset.a;if(p)new Audio(p).play().catch(()=>{})});let k=localStorage.socialAuditKey||(localStorage.socialAuditKey=crypto.randomUUID());respondent.value=k;show();</script><?php } ?></div></html>
